// Actual object Contents and Xfer packets over the connected production circuit.
#include "task_inventory_probe.hpp"
#include <map>
#include <iostream>
namespace opensim::tests {
namespace {
using framework::Uuid;using network::lludp::Packet;
void require(bool v,const char* message){if(!v)throw std::runtime_error(std::string("Task inventory UDP probe: ")+message);}
bool named(const Packet& p,const char* name){return p.spec&&p.spec->name==name;}
Packet reply(Uuid object,std::uint32_t local,const LegacyInventoryProbeIo& io){auto first=io.snapshot().size();auto request=io.make("RequestTaskInventory");request.block("InventoryData")["LocalID"]=std::uint64_t(local);io.send(request);auto matches=[&](const Packet& p){return named(p,"ReplyTaskInventory")&&std::get<Uuid>(p.block("InventoryData").at("TaskID"))==object;};io.wait([&](const auto& list){for(auto n=first;n<list.size();++n)if(matches(list[n]))return true;return false;});auto packets=io.snapshot();for(auto n=first;n<packets.size();++n)if(matches(packets[n])){require(packets[n].reliable&&!packets[n].zerocoded,"ReplyTaskInventory wire flags");return packets[n];}throw std::runtime_error("Missing task reply");}
std::uint32_t le(const std::vector<std::uint8_t>& b){require(b.size()>=4,"first chunk length header");return std::uint32_t(b[0])|(std::uint32_t(b[1])<<8)|(std::uint32_t(b[2])<<16)|(std::uint32_t(b[3])<<24);}
std::vector<std::uint8_t> download(std::uint64_t id,const std::vector<std::uint8_t>& filename,const LegacyInventoryProbeIo& io){auto cursor=io.snapshot().size();auto request=io.make("RequestXfer");auto& b=request.block("XferID");b["ID"]=id;b["Filename"]=filename;b["FilePath"]=std::uint64_t(99);b["DeleteOnCompletion"]=true;b["UseBigPackets"]=true;b["VFileType"]=std::int64_t(-1);io.send(request);
 auto matches=[&](const Packet& p){return named(p,"SendXferPacket")&&std::get<std::uint64_t>(p.block("XferID").at("ID"))==id;};std::map<std::uint32_t,std::vector<std::uint8_t>> pieces;std::optional<std::uint32_t> final,total;
 auto ack=[&](std::uint32_t n){auto packet=io.make("ConfirmXferPacket");packet.block("XferID")["ID"]=id;packet.block("XferID")["Packet"]=std::uint64_t(n);io.send(packet);};
 while(!final||!total||pieces.size()!=std::size_t(*final)+1){io.wait([&](const auto& list){for(auto n=cursor;n<list.size();++n)if(matches(list[n]))return true;return false;});auto packets=io.snapshot();for(;cursor<packets.size();++cursor){const auto& p=packets[cursor];if(!matches(p))continue;require(!p.reliable&&!p.zerocoded,"Xfer controller owns reliability");auto raw=static_cast<std::uint32_t>(std::get<std::uint64_t>(p.block("XferID").at("Packet")));auto number=raw&0x7fffffffu;require(number<1024,"bounded chunk index");auto bytes=std::get<std::vector<std::uint8_t>>(p.block("DataPacket").at("Data"));if(number==0){total=le(bytes);require(*total<1024*1024,"bounded fixture length");bytes.erase(bytes.begin(),bytes.begin()+4);}if(raw&0x80000000u)final=number;else require(bytes.size()==1024,"non-final payload size");auto [it,inserted]=pieces.emplace(number,bytes);require(inserted||it->second==bytes,"retry changed bytes");ack(raw);}}
 std::vector<std::uint8_t> result;for(const auto& [n,bytes]:pieces)result.insert(result.end(),bytes.begin(),bytes.end());require(result.size()==*total,"download length mismatch");ack(*final);return result;
}
}
DownloadedTaskInventory read_task_inventory_file(Uuid object,std::uint32_t local,std::int16_t serial,const LegacyInventoryProbeIo& io){auto packet=reply(object,local,io);require(std::get<std::int64_t>(packet.block("InventoryData").at("Serial"))==serial,"task serial");auto filename=std::get<std::vector<std::uint8_t>>(packet.block("InventoryData").at("Filename"));require(filename.size()==51&&filename.back()==0,"task filename");auto cached=reply(object,local,io);require(std::get<std::vector<std::uint8_t>>(cached.block("InventoryData").at("Filename"))==filename,"task cache reuse");auto bytes=download(0x1234000000000000ull+static_cast<std::uint16_t>(serial)*2,filename,io);require(bytes==download(0x1234000000000001ull+static_cast<std::uint16_t>(serial)*2,filename,io),"task cached bytes");require(!bytes.empty()&&bytes.back()==0,"task text terminator");return {{filename.begin(),filename.end()-1},{bytes.begin(),bytes.end()-1}};}
void check_empty_task_inventory(Uuid object,std::uint32_t local,const LegacyInventoryProbeIo& io){auto packet=reply(object,local,io);require(std::get<std::int64_t>(packet.block("InventoryData").at("Serial"))==0,"empty serial");require(std::get<std::vector<std::uint8_t>>(packet.block("InventoryData").at("Filename")).empty(),"empty filename");}
std::string check_task_inventory_download(Uuid agent,Uuid object,std::uint32_t local,std::int16_t serial,const LegacyInventoryProbeIo& io,const std::function<void(Uuid)>& verify_asset,const std::function<void(Uuid,Uuid)>& verify_running,int expected_items){auto packet=reply(object,local,io);const auto& b=packet.block("InventoryData");require(std::get<std::int64_t>(b.at("Serial"))==serial,"actual task mutation serial");auto filename=std::get<std::vector<std::uint8_t>>(b.at("Filename"));require(filename.size()==51&&filename.back()==0,"source filename format and terminator");std::string name(filename.begin(),filename.end()-1);require(name.starts_with("inventory_")&&name.ends_with(".tmp"),"source filename spelling");auto cached=reply(object,local,io);require(std::get<std::vector<std::uint8_t>>(cached.block("InventoryData").at("Filename"))==filename,"cache reuse filename");auto bytes=download(0x1234000000000000ull+static_cast<std::uint16_t>(serial)*2,filename,io);auto again=download(0x1234000000000001ull+static_cast<std::uint16_t>(serial)*2,filename,io);require(bytes==again,"cached registration/download bytes changed");require(!bytes.empty()&&bytes.back()==0,"inventory text UTF8 terminator");std::string text(bytes.begin(),bytes.end()-1);for(const auto& token:{std::string("obj_id\t")+object.str(),std::string("parent_id\t")+object.str(),std::string("owner_id\t")+agent.str(),std::string("creator_id\t")+agent.str(),std::string("group_mask\t00000000"),std::string("last_owner_id\t00000000-0000-0000-0000-000000000000"),std::string("inv_type\tscript"),std::string("name\tContents|"),std::string("name\tNew Script|")})require(text.find(token)!=text.npos,"actual task metadata missing");std::size_t asset_offset=0;while((asset_offset=text.find("asset_id\t",asset_offset))!=text.npos){asset_offset+=9;require(asset_offset+36<=text.size(),"script asset UUID length");Uuid asset(text.substr(asset_offset,36));require(!asset.is_zero(),"modifiable script asset disclosure");std::cout<<"Task script asset "<<asset.str()<<std::endl;if(verify_asset)verify_asset(asset);asset_offset+=36;}if(verify_running){std::size_t item_offset=0;while((item_offset=text.find("item_id\t",item_offset))!=text.npos){item_offset+=8;Uuid item(text.substr(item_offset,36));auto packet=io.make("GetScriptRunning");packet.block("Script")["ObjectID"]=object;packet.block("Script")["ItemID"]=item;io.send(packet);verify_running(object,item);item_offset+=36;}}std::size_t items=0,offset=0;while((offset=text.find("\tinv_item\t0\n",offset))!=text.npos){++items;++offset;}require(items==static_cast<std::size_t>(expected_items<0?static_cast<std::uint16_t>(serial):expected_items),"task item count differs from additions");if(serial>=2)require(text.find("name\tNew Script 1|")!=text.npos,"source duplicate script name suffix");std::cout<<"Verified task Contents serial "<<serial<<", "<<bytes.size()<<" actual Xfer bytes and cache reuse\n";return name;}
}
